A execução da função x descrita abaixo para o valor n igual a 8 fornecerá 21 como resultado.
```
long x(int n){
    if (n<0) return -1;
    if (n==0) return 0;
    if (n==1) return 1;
    return x(n-1) + x(n-2);
}
```

Considere tnode um nó de uma lista encadeada e a função monta_lista listados abaixo. Nesse caso, a utilização da função monta_lista criará uma lista encadeada com as informações ordenadas em ordem decrescente alfabeticamente e o ponteiro topo apontará para o nó com a maior informação alfabética.
```
struct tnode {
   char info[100];
   struct tnode *prox;
};
monta_lista(struct tnode **topo, struct tnode *p)) {
   struct tnode *atual, *ant;
   if (*topo == NULL) {
      *topo = p;
      return;
   }
   if (strcmp((*topo)->info, p->info) >= 0) {
      p->prox = *topo;
      *topo = p;
      return;
   }
   ant = *topo;
   atual = ant->prox;
   while (atual != NULL) {
      if (strcmp(atual->info,p->info) > 0){
         p->prox = atual;
         ant->prox = p;
         return;
      }
      ant = atual;
      atual = atual->prox;
   }
   ant->prox = p;
}
```
